			function doList(psStatus) {
			    
			    //조회 서브미션 호출
			    util.Submit.send(app, "subList", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            var dsBoardList = app.lookup("dsBoardList");
			            var dmPage = app.lookup("dmPage").getDatas();
			            
			            for(var idx = 0; idx < dsBoardList.getRowCount(); idx++){
			            	var row = dsBoardList.getRow(idx);
			            	
			            	var sn = dmPage["totalCount"] - idx - (dmPage["pageNo"] - 1) * dmPage["pageRowCount"];
			            	
			            	row.setValue("SN", sn);
			            	row.setState(cpr.data.tabledata.RowState.UNCHANGED);
			            }
			            
			            app.lookup("cmb4").focus();
			            
			            if (psStatus == "save") {
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			            } else {
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }
			        }
			    });
			}

